import asyncioimport subprocessimport sysimport discordimport yt_dlpimport mathimport osimport configparserimport platformimport requestsimport reimport unicodedataimport deamstoolsfrom urllib.parse import urlparse, parse_qsfrom main import bot, logw, api, log, add_help, FFMPEG_PATH, is_owner, logerr, loge, vcinuse_flagsconfig_file = 'MusicConfig.ini'cookiefile = 'cookie.txt'MusicConfig = configparser.ConfigParser(interpolation=None)default_config = {    'Messages': {        'Loading': '🎧 Loading... `[{query}]`',        'PlaybackResumed': '🎶 Playback resumed!',        'PlaybackPaused': '⏸ Playback paused.',        'PlaybackStopped': '⏹ Playback stopped and queue cleared.',        'QueueEmpty': '🎶 Your queue is currently empty.',        'NowPlaying': '🎵 Now playing: **[{title}](<{url}>)**',        'SongAdded': '➕ Added **{title}** to the queue at position {position}.',        'VolumeSet': '🔊 Volume set to {volume}%.',        'CurrentVolume': '🔊 Current volume: {volume}%.',        'PlaylistImport': 'Importing playlist... Found {count} songs',        'PlaylistImported': 'Successfully imported {count} songs from playlist: **{title}**',        'PlaylistChoice': 'This video is part of a playlist. React with:\n🎵 - Import just this video\n📋 - Import entire playlist ({count} songs)',    },    'Defaults': {        'Volume': '1.0',        'RepeatMode': 'all',    },    'account': {        'username': '',        'password': '',        'cookie': 'cookie.txt'    }}if not os.path.exists(config_file):    MusicConfig.read_dict(default_config)    with open(config_file, 'w', encoding='utf-8') as configfile:        MusicConfig.write(configfile)else:    MusicConfig.read(config_file, encoding='utf-8')messages = MusicConfig['Messages']YDL_OPTIONS = {    'format': 'bestaudio[ext=webm]/bestaudio',  # Forces WebM first, otherwise best audio    'noplaylist': True,  # Ensures only one song is downloaded    'outtmpl': 'playing.%(ext)s',  # Saves as "playing.<ext>"    'quiet': True,  # Suppresses logs    'no_warnings': True,  # Hides warnings    'default_search': 'auto',  # Enables auto search    'verbose': False,  # Disables verbose logs    'cookies': MusicConfig['account']['cookie'],  # Uses cookies for authentication}YDL_PLAYLIST_OPTIONS = {    'format': 'bestaudio[ext=webm]/bestaudio',    'quiet': True,    'no_warnings': True,    'extract_flat': True,  # Only extract metadata, don't download    'cookies': MusicConfig['account']['cookie'],}if (MusicConfig['account']['username'] and MusicConfig['account']['username']) != '':    YDL_OPTIONS['username'] = MusicConfig['account']['username']    YDL_OPTIONS['password'] = MusicConfig['account']['password']    YDL_PLAYLIST_OPTIONS['username'] = MusicConfig['account']['username']    YDL_PLAYLIST_OPTIONS['password'] = MusicConfig['account']['password']FFMPEG_OPTIONS = {    'executable': FFMPEG_PATH,    'options': '-vn',}def check_yt_dlp():    log('Checking for Yt DLP update')    code = deamstools.check_for_package_updates('yt-dlp')[1]    if code == 200:        log('YT DLP Upto Date!')    elif code == 404:        logerr('Error Getting YT Dlp Error')    elif code == 202:        logw('YT DLP Outdated, Restart bot to update!')        subprocess.run([sys.executable, '-m', 'pip', 'install', '-U', 'yt-dlp'])    else:        loge('Error checking for YT Dlp update')    return codecheck_yt_dlp()server_data = {}load_locks = {}playlists_folder = 'Playlists'playlist_choice_timeout = 30def get_server_data(guild_id):    """Get or create server-specific data"""    if guild_id not in server_data:        server_data[guild_id] = {            'queue': [],            'repeat_mode': MusicConfig.get('Defaults', 'RepeatMode'),            'current_song': (None, None),            'stopped': False,            'volume': float(MusicConfig.get('Defaults', 'Volume')),        }    return server_data[guild_id]def get_load_lock(guild_id):    """Get or create server-specific load lock"""    if guild_id not in load_locks:        load_locks[guild_id] = asyncio.Lock()    return load_locks[guild_id]def is_playlist_url(url):    """Check if URL is a YouTube playlist"""    try:        parsed = urlparse(url)        if 'youtube.com' in parsed.netloc or 'youtu.be' in parsed.netloc:            # Check for playlist parameter            if 'list=' in url:                return True            # Check for playlist in path (for some mobile URLs)            if '/playlist' in parsed.path:                return True        return False    except Exception:        return Falsedef is_video_in_playlist(url):    """Check if URL is a video that's part of a playlist"""    try:        parsed = urlparse(url)        if 'youtube.com' in parsed.netloc:            query_params = parse_qs(parsed.query)            # Must have both video ID and playlist ID            return 'v' in query_params and 'list' in query_params and query_params['list'][0] != ''        return False    except Exception:        return Falsedef extract_playlist_id_from_video_url(url):    """Extract playlist ID from a video URL that contains playlist info"""    try:        parsed = urlparse(url)        query_params = parse_qs(parsed.query)        playlist_id = query_params.get('list', [None])[0]        # Validate that it's not empty and looks like a playlist ID        if playlist_id and playlist_id.strip() and not playlist_id.startswith('WL'):  # WL is "Watch Later"            return playlist_id        return None    except Exception:        return Nonedef get_video_id_from_url(url):    """Extract video ID from YouTube URL"""    try:        parsed = urlparse(url)        if 'youtube.com' in parsed.netloc:            query_params = parse_qs(parsed.query)            return query_params.get('v', [None])[0]        elif 'youtu.be' in parsed.netloc:            return parsed.path[1:]  # Remove the leading slash    except:        pass    return Noneasync def get_playlist_info(playlist_url):    """Get playlist information and video URLs"""    try:        def extract_playlist():            # More robust options for playlist extraction            playlist_opts = {                'quiet': True,                'no_warnings': True,                'extract_flat': True,                'ignoreerrors': True,  # Continue on errors                'skip_download': True,                'playlistend': 100,  # Limit to first 100 songs to avoid timeouts                'no_color': True,            }            # Add cookies if available            if MusicConfig['account']['cookie'] and os.path.exists(MusicConfig['account']['cookie']):                playlist_opts['cookies'] = MusicConfig['account']['cookie']            # Add username/password if available            if (MusicConfig['account']['username'] and MusicConfig['account']['password'] and                    MusicConfig['account']['username'] != '' and MusicConfig['account']['password'] != ''):                playlist_opts['username'] = MusicConfig['account']['username']                playlist_opts['password'] = MusicConfig['account']['password']            with yt_dlp.YoutubeDL(playlist_opts) as ydl:                return ydl.extract_info(playlist_url, download=False)        #print(f"Attempting to extract playlist: {playlist_url}")        info = await asyncio.to_thread(extract_playlist)        if not info:            print("No info returned from yt-dlp")            return None, []        #print(f"Info keys: {info.keys() if info else 'None'}")        #print(f"Info type: {info.get('_type', 'unknown')}")        # Handle different response types        if info.get('_type') == 'playlist' and 'entries' in info:            # Standard playlist format            playlist_title = info.get('title', info.get('uploader', 'Unknown Playlist'))            entries = []            #print(f"Found {len(info['entries'])} entries in playlist")            for i, entry in enumerate(info['entries']):                if entry and entry.get('id'):                    try:                        video_url = f"https://www.youtube.com/watch?v={entry['id']}"                        video_title = entry.get('title', f'Video {i + 1}')                        entries.append((video_url, video_title))                        #print(f"Added: {video_title}")                    except Exception as e:                        print(f"Error processing entry {i}: {e}")                        continue                else:                    print(f"Skipping invalid entry {i}: {entry}")            #print(f"Successfully extracted {len(entries)} videos from playlist")            return playlist_title, entries        elif info.get('_type') == 'url' and info.get('ie_key') == 'Youtube':            # This might be a redirect to another URL, try to re-extract            #print("Found redirect URL, attempting to re-extract...")            redirect_url = info.get('url') or info.get('webpage_url')            if redirect_url and redirect_url != playlist_url:                return await get_playlist_info(redirect_url)            else:                print("No valid redirect URL found")                return None, []        elif 'entries' not in info:            print("No entries found in playlist info")            if info.get('id') and not info.get('_type') == 'playlist':                playlist_title = info.get('uploader', 'Single Video')                video_url = info.get('webpage_url') or f"https://www.youtube.com/watch?v={info['id']}"                video_title = info.get('title', 'Unknown Title')                print(f"Treating as single video: {video_title}")                return playlist_title, [(video_url, video_title)]            try:                def extract_full_info():                    alt_opts = {                        'quiet': True,                        'no_warnings': True,                        'extract_flat': False,                        'ignoreerrors': True,                        'skip_download': True,                        'playlistend': 50,                    }                    if MusicConfig['account']['cookie'] and os.path.exists(MusicConfig['account']['cookie']):                        alt_opts['cookies'] = MusicConfig['account']['cookie']                    if (MusicConfig['account']['username'] and MusicConfig['account']['password'] and                            MusicConfig['account']['username'] != '' and MusicConfig['account']['password'] != ''):                        alt_opts['username'] = MusicConfig['account']['username']                        alt_opts['password'] = MusicConfig['account']['password']                    with yt_dlp.YoutubeDL(alt_opts) as ydl:                        return ydl.extract_info(playlist_url, download=False)                alt_info = await asyncio.to_thread(extract_full_info)                if alt_info and 'entries' in alt_info:                    playlist_title = alt_info.get('title', alt_info.get('uploader', 'Unknown Playlist'))                    entries = []                    for i, entry in enumerate(alt_info['entries']):                        if entry and entry.get('webpage_url'):                            try:                                video_url = entry['webpage_url']                                video_title = entry.get('title', f'Video {i + 1}')                                entries.append((video_url, video_title))                            except Exception as e:                                print(f"Error processing alt entry {i}: {e}")                                continue                    if entries:                        print(f"Alternative method found {len(entries)} videos")                        return playlist_title, entries            except Exception as e:                print(f"Alternative extraction method failed: {e}")            return None, []        else:            playlist_title = info.get('title', info.get('uploader', 'Unknown Playlist'))            entries = []            for i, entry in enumerate(info.get('entries', [])):                if entry and entry.get('id'):                    try:                        video_url = f"https://www.youtube.com/watch?v={entry['id']}"                        video_title = entry.get('title', f'Video {i + 1}')                        entries.append((video_url, video_title))                    except Exception as e:                        print(f"Error processing entry {i}: {e}")                        continue                else:                    print(f"Skipping invalid entry {i}: {entry}")            print(f"Successfully extracted {len(entries)} videos from playlist")            return playlist_title, entries    except Exception as e:        print(f'Error extracting playlist info: {e}')        import traceback        traceback.print_exc()        return None, []def normalize_to_playlist_url(url):    playlist_id = extract_playlist_id_from_video_url(url)    return f"https://www.youtube.com/playlist?list={playlist_id}" if playlist_id else urlasync def handle_video_in_playlist_choice(ctx, video_url):    playlist_id = extract_playlist_id_from_video_url(video_url)    if not playlist_id:        return video_url    playlist_url = f"https://www.youtube.com/playlist?list={playlist_id}"    try:        playlist_url = normalize_to_playlist_url(video_url)        playlist_title, entries = await get_playlist_info(playlist_url)        if not entries or len(entries) <= 1:            video_id = get_video_id_from_url(video_url)            return f"https://www.youtube.com/watch?v={video_id}" if video_id else video_url        choice_message = await ctx.send(messages['PlaylistChoice'].format(count=len(entries)))        await choice_message.add_reaction('🎵')        await choice_message.add_reaction('📋')        def check(reaction, user):            return (user == ctx.author and                    str(reaction.emoji) in ['🎵', '📋'] and                    reaction.message.id == choice_message.id)        try:            reaction, user = await bot.wait_for('reaction_add', timeout=playlist_choice_timeout, check=check)            if str(reaction.emoji) == '📋':                await choice_message.edit(content=messages['Loading'].format(query="playlist"))                success = await import_playlist_to_queue(ctx, playlist_url, choice_message)                if success and not ctx.guild.voice_client.is_playing():                    await play_next(ctx)                return None            else:                await choice_message.delete()                video_id = get_video_id_from_url(video_url)                return f"https://www.youtube.com/watch?v={video_id}" if video_id else video_url        except asyncio.TimeoutError:            await choice_message.edit(content="⏰ Choice timed out, importing just the video.")            await choice_message.clear_reactions()            video_id = get_video_id_from_url(video_url)            return f"https://www.youtube.com/watch?v={video_id}" if video_id else video_url    except Exception as e:        print(f"Error getting playlist info for choice: {e}")        video_id = get_video_id_from_url(video_url)        return f"https://www.youtube.com/watch?v={video_id}" if video_id else video_urlasync def get_song_info(query):    try:        def extract_info(query):            with yt_dlp.YoutubeDL({'quiet': True}) as ydl:                if 'youtube.com/watch' in query or 'youtu.be' in query:                    return ydl.extract_info(query, download=False)                else:                    search_url = f"ytsearch:{query}"                    return ydl.extract_info(search_url, download=False)        info = await asyncio.to_thread(extract_info, query)        if 'entries' in info:            info = info['entries'][0]        title = info.get('title', 'Unknown title')        url = info.get('webpage_url', query)        return title, url    except yt_dlp.utils.ExtractorError as e:        print(f'Error retrieving song info: {e}')        return None, None    except Exception as e:        print(f'Unexpected error: {e}')        return None, Noneasync def get_stream_url(url):    try:        def extract_stream_url():            ydl_opts = {                'quiet': True,                'format': 'bestaudio/best',                'noplaylist': True,            }            with yt_dlp.YoutubeDL(ydl_opts) as ydl:                info = ydl.extract_info(url, download=False)                return info['url'] if 'url' in info else None        return await asyncio.to_thread(extract_stream_url)    except Exception as e:        print(f'Error getting stream URL: {e}')        return Noneasync def play_next(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    voice_client = ctx.guild.voice_client    if not voice_client or not voice_client.is_connected():        if ctx.author.voice and ctx.author.voice.channel:            channel = ctx.author.voice.channel            voice_client = await channel.connect()        else:            await ctx.send('I need to be in a voice channel to play music!')            return    if data['queue']:        url, title = data['queue'].pop(0)        stream_url = await get_stream_url(url)        if not stream_url:            await ctx.send(f"❌ Failed to get stream URL for: {title}")            return        def after_playback(err):            try:                if data['stopped']:                    data['stopped'] = False                    return                if data.get('paused_by_user'):                    return                if err:                    print(f"Playback error: {err}")                # Repeat handling                if data['repeat_mode'] == 'all':                    data['queue'].append((url, title))                elif data['repeat_mode'] == 'single':                    data['queue'].insert(0, (url, title))                if data['queue']:                    bot.loop.create_task(play_next(ctx))                else:                    data['current_song'] = (None, None)                    if 'vcinuse_flags' in globals():                        vcinuse_flags[str(ctx.guild.id)] = False            except Exception as e:                print(f"Exception in after_playback: {e}")        if data['stopped']:            data['stopped'] = False            return        audio_source = discord.FFmpegPCMAudio(            stream_url,            executable=FFMPEG_PATH,            before_options='-reconnect 1 -reconnect_streamed 1 -reconnect_delay_max 5',            options='-vn'        )        audio_source = discord.PCMVolumeTransformer(audio_source, volume=data['volume'])        if not voice_client.is_playing():            voice_client.play(audio_source, after=after_playback)            data['current_song'] = (url, title)    else:        data['current_song'] = (None, None)        if 'vcinuse_flags' in globals():            vcinuse_flags[str(ctx.guild.id)] = Falsedef sanitize_title(title: str) -> str:    normalized = unicodedata.normalize('NFKD', title).encode('ASCII', 'ignore').decode('utf-8')    sanitized = re.sub(r'[\\/*?:"<>|]', '', normalized)    sanitized = re.sub(r'\s+', ' ', sanitized).strip()    return sanitizedasync def add_to_queue(ctx, query):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    title, url = await get_song_info(query)    title = sanitize_title(title)    if title is None or url is None:        print(f'Could not retrieve song information. {query}')        return None, None, None    data['queue'].append((url, title))    position = len(data['queue'])    return title, url, positionasync def import_playlist_to_queue(ctx, playlist_url, loading_message=None):    """Import entire playlist to queue"""    guild_id = ctx.guild.id    data = get_server_data(guild_id)    playlist_url = normalize_to_playlist_url(playlist_url)    #print(playlist_url)    playlist_title, entries = await get_playlist_info(playlist_url)    if not entries:        error_msg = "❌ Could not load playlist. This might be due to:\n• Private playlist\n• Age-restricted content\n• Geographic restrictions\n• YouTube API limitations\n\nTry using individual video URLs instead."        if loading_message:            await loading_message.edit(content=error_msg)        else:            await ctx.send(error_msg)        return False    if loading_message:        await loading_message.edit(content=messages['PlaylistImport'].format(count=len(entries)))    # Add all songs to queue    added_count = 0    for video_url, video_title in entries:        try:            sanitized_title = sanitize_title(video_title)            data['queue'].append((video_url, sanitized_title))            added_count += 1        except Exception as e:            print(f"Error adding {video_title} to queue: {e}")            continue    success_msg = messages['playlistimported'].format(count=added_count, title=playlist_title)    if loading_message:        await loading_message.edit(content=success_msg)    else:        await ctx.send(success_msg)    return added_count > 0@bot.command(name='play', aliases=['p', 'P', 'Play'])async def play_command(ctx, *, query: str = None):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    data['stopped'] = False    voice_client = ctx.guild.voice_client    if 'vcinuse_flags' in globals():        vcinuse_flags[str(ctx.guild.id)] = True    if voice_client and voice_client.is_paused() and not query:        voice_client.resume()        data['paused_by_user'] = False        await ctx.send(messages['PlaybackResumed'])        return    if not query:        await ctx.send('Please provide a query or link')        return    if not ctx.author.voice:        await ctx.send('You are not connected to a voice channel!')        return    channel = ctx.author.voice.channel    if ctx.guild.voice_client:        if ctx.guild.voice_client.channel != channel:            await ctx.guild.voice_client.move_to(channel)    else:        await channel.connect()        await asyncio.sleep(2)    # Handle local playlist loading    if query.startswith('pl '):        playlist = query.replace('pl ', '', 1)        path = f'{playlists_folder}/{playlist}.txt'        if os.path.exists(path):            loading_message = await ctx.send(f'Loading playlist {playlist}')            with open(path, 'r', encoding='utf-8') as f:                playlist_songs = f.readlines()            if not playlist_songs:                await ctx.send('Playlist is empty!')                return            song_count = 0            for song in playlist_songs:                if not song.strip():                    continue                await add_to_queue(ctx, song.strip())                if not ctx.guild.voice_client.is_playing():                    await play_next(ctx)                song_count += 1            await loading_message.edit(content=f'Loaded {song_count} songs')            return    if is_video_in_playlist(query):        processed_query = await handle_video_in_playlist_choice(ctx, query)        if processed_query is None:            return        else:            query = processed_query    if is_playlist_url(query):        loading_message = await ctx.send(messages['Loading'].format(query=query))        success = await import_playlist_to_queue(ctx, query, loading_message)        if success and not ctx.guild.voice_client.is_playing():            await play_next(ctx)        return    # Handle single video/search query    loading_message = await ctx.send(messages['Loading'].format(query=query))    load_lock = get_load_lock(guild_id)    async with load_lock:        title, url, position = await add_to_queue(ctx, query)        if title is None or url is None:            await loading_message.edit(content="❌ Could not find or load the song.")            return        title = sanitize_title(title)        if ctx.guild.voice_client.is_playing() or position > 1:            await loading_message.edit(content=messages['SongAdded'].format(title=title, position=position))            return        if not ctx.guild.voice_client.is_playing():            await play_next(ctx)        if title:            await loading_message.edit(content=messages['NowPlaying'].format(title=title, url=url))add_help('Music', 'play [search query/URL/playlist URL]',         'Searches youtube with provided query to play music, import playlists, or resume paused music')@bot.command(name='pause')async def pause_command(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    voice_client = ctx.guild.voice_client    if voice_client and voice_client.is_playing():        voice_client.pause()        data['paused_by_user'] = True        await ctx.send(messages['PlaybackPaused'])    else:        await ctx.send("I am not playing anything right now!")@bot.command(name='resume')async def resume_command(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    voice_client = ctx.guild.voice_client    if voice_client and voice_client.is_paused():        voice_client.resume()        data['paused_by_user'] = False        await ctx.send(messages['PlaybackResumed'])    else:        await ctx.send("I am not playing anything right now!")add_help('Music', 'resume', 'Resumes the player')@bot.command(name='skip', aliases=['next'])async def skip(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    data['stopped'] = True    voice_client = ctx.guild.voice_client    if voice_client and voice_client.is_playing():        voice_client.stop()        await ctx.send('Skipped the current song.')        data['queue'].append(data['current_song'])        await play_next(ctx)    else:        await ctx.send('No song is currently playing to skip!')add_help('Music', 'skip', 'Skips the current song')@bot.command(name='skipto')async def skipto(ctx, position: int):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    data['stopped'] = True    voice_client = ctx.guild.voice_client    if position < 1 or position > len(data['queue']):        await ctx.send('Invalid position in the queue!')        return    if voice_client and voice_client.is_playing():        data['queue'].insert(0, data['current_song'])        data['queue'] = data['queue'][position:] + data['queue'][:position]        voice_client.stop()        await ctx.send(f'Skipped to position {position} in the queue.')        await play_next(ctx)    else:        await ctx.send('No song is currently playing!')add_help('Music', 'skipto <pos>', 'skips to the given position')@bot.command(name='stop')async def stop(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    data['stopped'] = True    voice_client = ctx.guild.voice_client    # Update vcinuse_flags if it exists    if 'vcinuse_flags' in globals():        vcinuse_flags[str(ctx.guild.id)] = False    if voice_client:        if voice_client.is_playing() or voice_client.is_paused():            voice_client.stop()        await voice_client.disconnect()        data['queue'] = []        data['current_song'] = (None, None)        if os.path.exists('playing.webm'):            os.remove('playing.webm')        await ctx.send(messages['PlaybackStopped'])    else:        await ctx.send("I am not connected to a voice channel!")add_help('Music', 'stop', 'stops the player')@bot.command(name='volume', aliases=['vol'])async def set_volume(ctx, vol: int = None):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if vol is None:        await ctx.send(messages['CurrentVolume'].format(volume=int(data['volume'] * 100)))        return    if vol < 0 or vol > 200:        await ctx.send('Volume must be between 0 and 200')        return    data['volume'] = vol / 100.0    voice_client = ctx.guild.voice_client    if voice_client and voice_client.source:        voice_client.source.volume = data['volume']    await ctx.send(messages['VolumeSet'].format(volume=int(data['volume'] * 100)))add_help('Music', 'volume <percentage>', 'Sets the volume percentage')@bot.command(name='repeat', aliases=['r', 'loop'])async def repeat_command(ctx, mode: str = None):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if mode is None:        await ctx.send(f'Current repeat mode is {data["repeat_mode"]}.')        return    mode = mode.lower()    if mode in ('all', 'single', 'off'):        data['repeat_mode'] = mode        await ctx.send(f'Repeat mode set to {data["repeat_mode"]}.')    else:        await ctx.send('Invalid repeat mode. Use `all`, `single`, or `off`.')add_help('Music', 'repeat [all/single/off]', 'Tells you to current loop setting ir also changes it to the given one')@bot.command(name='queue', aliases=['q'])async def queue_list(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if not data['queue']:        await ctx.send("📭 The queue is currently empty.")        return    queue = data['queue']    items_per_page = 10    pages = math.ceil(len(queue) / items_per_page)    def get_page_content(page):        start = page * items_per_page        end = start + items_per_page        page_queue = queue[start:end]        queue_message = '\n'.join([f"**{i+1+start}.** [{title}](<{url}>)" for i, (url, title) in enumerate(page_queue)])        embed = discord.Embed(title="🎶 Music Queue", description=queue_message, color=discord.Color.blurple())        embed.set_footer(text=f"Page {page + 1} of {pages}")        return embed    current_page = 0    message = await ctx.send(messages['NowPlaying'].format(title=data['current_song'][1], url=data['current_song'][0]) ,embed=get_page_content(current_page))    if pages <= 1:        return    await message.add_reaction("⬅️")    await message.add_reaction("➡️")    def check(reaction, user):        return user == ctx.author and str(reaction.emoji) in ["⬅️", "➡️"] and reaction.message.id == message.id    while True:        try:            reaction, user = await bot.wait_for("reaction_add", timeout=60.0, check=check)            if str(reaction.emoji) == "➡️" and current_page < pages - 1:                current_page += 1                await message.edit(messages['NowPlaying'].format(title=data['current_song'][1], url=data['current_song'][0]), embed=get_page_content(current_page))            elif str(reaction.emoji) == "⬅️" and current_page > 0:                current_page -= 1                await message.edit(messages['NowPlaying'].format(title=data['current_song'][1], url=data['current_song'][0]), embed=get_page_content(current_page))            await message.remove_reaction(reaction.emoji, user)        except asyncio.TimeoutError:            try:                await message.clear_reactions()            except:                pass            breakadd_help('Music', 'queue', 'Shows you the current queue')@bot.command(name='move')async def move(ctx, from_position: int, to_position: int):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if from_position < 1 or from_position > len(data['queue']) or to_position < 1 or to_position > len(data['queue']):        await ctx.send('Invalid positions in the queue!')        return    song = data['queue'].pop(from_position - 1)    data['queue'].insert(to_position - 1, song)    await ctx.send(f'Moved song from position {from_position} to {to_position} in the queue.')add_help('Music', 'move <pos> <pos>', 'moves a song it the queue from one position to the other')@bot.command(name='current', aliases=['np', 'nowplaying'])async def current_command(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if data['current_song'][1]:        await ctx.send(messages['NowPlaying'].format(title=data['current_song'][1], url=data['current_song'][0]))    else:        await ctx.send(messages['QueueEmpty'])add_help('Music', 'current', 'tells you the current song playing')@bot.group(name='playlist', aliases=['pl'], invoke_without_command=True)async def playlist_command(ctx):    await ctx.send("Use subcommand add/remove/list/append")add_help('Music', 'playlist <add/remove/list/append>', 'playlist management commands')@playlist_command.command(name='add', aliases=['make'])async def playlist_add(ctx, name: str = None):    if not name:        await ctx.send('Please provide a playlist name!')        return    playlist = f'{name}.txt'    if os.path.exists(f'{playlists_folder}/{playlist}'):        await ctx.send('Playlist already exists!')        return    os.makedirs(playlists_folder, exist_ok=True)    with open(f'{playlists_folder}/{playlist}', 'w', encoding='utf-8') as f:        f.write('')        await ctx.send(f'**Created playlist {name}!**')@playlist_command.command(name='remove', aliases=['delete', 'del'])async def playlist_remove(ctx, name: str = None):    if not name:        await ctx.send('Please provide a playlist name!')        return    playlist = f'{name}.txt'    if not os.path.exists(f'{playlists_folder}/{playlist}'):        await ctx.send('Playlist does not exists!')        return    os.remove(f'{playlists_folder}/{playlist}')    await ctx.send(f'**Playlist {name} removed!**')@playlist_command.command(name='list')async def playlist_list(ctx):    response = '# Available playlists'    if not os.path.exists(playlists_folder) or not os.listdir(playlists_folder):        await ctx.send('No playlists available')        return    for file in os.listdir(playlists_folder):        if file.endswith('.txt'):            response = response + f"\n {file.replace('.txt', '')}"    await ctx.send(response)@playlist_command.command(name='append')async def playlist_append(ctx, name: str = None, *, query: str = None):    if not name:        await ctx.send('Please provide a playlist name!')        return    if not query:        await ctx.send('Please provide a query or url')        return    playlist = f'{name}.txt'    if not os.path.exists(f'{playlists_folder}/{playlist}'):        await ctx.send('Playlist does not exists!')        return    with open(f'{playlists_folder}/{playlist}', 'a', encoding='utf-8') as f:        f.write('\n' + query)        await ctx.send(f'**Appended {query} to playlist {name}!**')@playlist_command.command(name='dump')async def playlist_dump(ctx, name: str = None):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if not name:        await ctx.send('Please provide a playlist name to dump into!')        return    if not data['queue']:        await ctx.send('The queue is currently empty, nothing to dump!')        return    playlist = f'{name}.txt'    os.makedirs(playlists_folder, exist_ok=True)    path = f'{playlists_folder}/{playlist}'    if not os.path.exists(path):        await ctx.send('Playlist does not exists!')        return    try:        with open(path, 'a', encoding='utf-8') as f:            for url, _ in data['queue']:                f.write(url + '\n')        await ctx.send(f'✅ Appended **{len(data["queue"])}** songs to playlist **{name}**.')    except Exception as e:        print(f"Error dumping playlist: {e}")        await ctx.send("❌ Failed to append queue to playlist.")@bot.command(name='remove', aliases=['delete', 'del'])async def remove(ctx, position: str = "0"):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if position == 'all':        data['queue'] = []        await ctx.send(f'Queue cleared!')        return    try:        position = int(position)    except ValueError:        await ctx.send('Invalid position! Use a number or "all".')        return    if position < 1 or position > len(data['queue']):        await ctx.send('Invalid position in the queue!')        return    removed_song = data['queue'].pop(position - 1)    await ctx.send(f'Removed song at position {position}: {removed_song[1]} from the queue.')add_help('Music', 'remove <pos|all>', 'removes a song from the queue at the given position or clears all')@is_owner()@bot.command(name='ts')async def troubleshoot(ctx):    await ctx.send('Checking...')    await ctx.send('YT DLP Outdated, Restart Bot Now!' if check_yt_dlp() == 202 else 'Everything Seems Fine!')add_help('Music', 'ts', 'Checks for Yt Dlp Updates, run if bot giving error related to ytdlp')